package resource

// The page templates. They use [[ ]] delimiters, so the Svelte braces need no
// escapes.

// schemaTS is the model of the pages: the zod schema of the form, the
// conversions between the API and the form, and the display helpers.
const schemaTS = `// The form of a [[ .Words ]]: the zod schema that checks the inputs, the conversions between the
// API and the form values, and the display helpers of the pages.
// Generated by spinup g resource. The application owns this file.
import { z } from 'zod';
import type { components } from '#lib/api/schema.js';

/** Item is a [[ .Words ]] as the API returns it. */
export type Item = components['schemas']['[[ .Pascal ]]'];
/** Input is the JSON body of a create or a full update. */
export type Input = components['schemas']['[[ .Pascal ]]Input'];
/** Problem is an API error (RFC 9457 problem details). */
export type Problem = components['schemas']['Problem'];

/** schema checks the form values. Superforms also reads the values of a new [[ .Words ]] from it. */
export const schema = z.object({
[[- range $i, $f := .Fields ]][[ if $i ]],[[ end ]]
	[[ $f.Col ]]: [[ $f.Zod ]]
[[- end ]]
});

/** Values holds the form values of a [[ .Words ]]. */
export type Values = z.infer<typeof schema>;
[[- range .Enums ]]

/** The labels of the [[ .Col ]] values. */
export const [[ .Labels ]]: Record<NonNullable<Item['[[ .Col ]]']>, string> = {
[[- range $i, $o := .Options ]][[ if $i ]],[[ end ]]
	[[ $o.Key ]]: '[[ $o.Label ]]'
[[- end ]]
};
[[- end ]]

/** fromItem returns the form values of a [[ .Words ]], for the edit form. */
export function fromItem(item: Item): Values {
	return {
[[- range $i, $f := .Fields ]][[ if $i ]],[[ end ]]
		[[ $f.Col ]]: [[ $f.FromItem ]]
[[- end ]]
	};
}

[[ if .Time -]]
/**
 * toBody returns the JSON body of the API for checked form values. Pass the stored [[ .Words ]]
 * on an update: a time that did not change keeps its full precision.
 */
[[ else -]]
/** toBody returns the JSON body of the API for checked form values. */
[[ end -]]
export function toBody(values: Values[[ if .Time ]], original?: Item[[ end ]]): Input {
	return {
[[- range $i, $f := .Fields ]][[ if $i ]],[[ end ]]
		[[ $f.Col ]]: [[ $f.ToBody ]]
[[- end ]]
	};
}

/** itemTitle returns the name of a [[ .Words ]] in headings and links. */
export function itemTitle(item: Item): string {
[[- if .TitleCol ]]
	return item.[[ .TitleCol ]] || ` + "`" + `[[ .Name ]] ${item.id}` + "`" + `;
[[- else ]]
	return ` + "`" + `[[ .Name ]] ${item.id}` + "`" + `;
[[- end ]]
}
[[- if .Date ]]

// A date has no time zone. Format it in UTC, so the day does not shift.
const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeZone: 'UTC' });

/** formatDate formats a date such as 2026-10-16 for the reader. */
export function formatDate(value: string): string {
	return dateFormat.format(new Date(value));
}
[[- end ]]

const timeFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' });

/** formatTime formats an instant in the time zone of the reader. */
export function formatTime(value: string): string {
	return timeFormat.format(new Date(value));
}

/** problemMessage returns the text of an API problem. */
export function problemMessage(problem: Problem | undefined, status: number): string {
	return problem?.detail ?? problem?.title ?? ` + "`" + `The API returned status ${status}.` + "`" + `;
}
[[- if .Time ]]

// The datetime-local inputs show UTC times without a zone.
function localTime(value: string): string {
	return new Date(value).toISOString().slice(0, 19);
}

// time returns the instant of an input value. Browsers can drop the seconds and fractions, so
// an input that still shows the original instant keeps the original value.
function time(value: string, original?: string | null): string {
	const t = new Date(value + 'Z');
	if (original && t.getTime() === new Date(localTime(original) + 'Z').getTime()) return original;
	return t.toISOString();
}
[[- end ]]
[[- if .JSON ]]

// isObject reports whether text is a JSON object.
function isObject(text: string): boolean {
	try {
		const value: unknown = JSON.parse(text);
		return typeof value === 'object' && value !== null && !Array.isArray(value);
	} catch {
		return false;
	}
}
[[- end ]]
`
